using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns a greeting for the given name.")]
    public static string Greet(
        [Description("The name to greet")] string name) =>
        $"Hello, {name}! Welcome to the HTTP MCP server.";

    [McpServerTool, Description("Adds two numbers and returns the result.")]
    public static double Add(
        [Description("First number")] double a,
        [Description("Second number")] double b) =>
        a + b;
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ServerResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration.")]
    public static string GetAppSettings() =>
        JsonSerializer.Serialize(new
        {
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { EnableCaching = true, EnableLogging = true }
        }, new JsonSerializerOptions { WriteIndented = true });
}

